import{createFrameLighting}from'../jisepo_daynight_consumer/frame-lighting.mjs';const ambient=createFrameLighting({nightTint:[.4,.47,.6]});export function compose(host,assets,meta){const m=assets.manifest,no=reason=>({available:false,reason});if(!(host instanceof Uint8ClampedArray)||m?.revision!=='POW_PARK_ACTUAL_LIGHTS_R1'||meta?.sourceSHA!==m.sourceSHA||meta.verified!==true||meta.alreadyApplied!==false||!Number.isFinite(meta.nightMix)||meta.nightMix<0||meta.nightMix>1||!Array.isArray(meta.camera)||meta.camera.length!==4)return no('invalid-state');const[x,y,w,h]=meta.camera;if(![x,y,w,h].every(Number.isInteger)||x<0||y<0||w<1||h<1||x+w>1536||y+h>1024||host.length!==w*h*4)return no('invalid-camera');const ids=assets.ids,t=assets.transmission;if(!(ids instanceof Uint32Array)||!(t instanceof Float64Array)||ids.length!==m.count||t.length!==m.count*3)return no('invalid-payload');ambient(host,host,meta.nightMix);let writes=0;if(meta.nightMix>0&&!meta.lightBad&&meta.lightsEnabled!==false)for(let i=0;i<ids.length;i++){const xx=ids[i]%1536,yy=Math.floor(ids[i]/1536);if(xx<x||xx>=x+w||yy<y||yy>=y+h)continue;const k=((yy-y)*w+xx-x)*4;for(let c=0;c<3;c++)host[k+c]=Math.round(255-(255-host[k+c])*(1-meta.nightMix*(1-t[i*3+c])));writes++;}return{available:true,writes,ambientApplications:meta.nightMix>0?1:0};}
